begin;
select plan(21);
select is((select count(*)::integer from public.categories),7,'Siete categorías fuente');
select is((select count(*)::integer from public.catalog_items),29,'29 referencias C01-C24/P01-P05');
select is((select count(*)::integer from public.promotions),5,'Cinco promociones independientes');
select ok((select not online_enabled from public.catalog_items where source_ref='C01'),'Precio de mesa fuera de web');
select ok(not exists(select 1 from public.catalog_prices p join public.catalog_items i on i.id=p.item_id where i.source_ref='P05' and p.mode='pickup'),'P05 no ofrece recojo');
select is((select count(*)::integer from public.catalog_items where source_ref like 'C%' and source_ref not in ('C01')) ,23,'Entradas comerciales conservadas');
select ok((select bool_and(portion_label='4 alitas') from public.catalog_items where source_ref in ('C07','C08','C09','C10','C11')),'Alitas de cuatro unidades');
select is((select portion_label from public.catalog_items where source_ref='P03'),'16 alitas','Ronda de dieciséis');
select ok((select bool_and(c.relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('categories','catalog_items','catalog_prices','promotions','option_groups','option_choices')),'Seis tablas con RLS');
select ok(not has_table_privilege('anon','public.catalog_items','select,insert,update,delete'),'Anónimo sin CRUD de artículos');
select ok(not has_table_privilege('authenticated','public.catalog_prices','select,insert,update,delete'),'Autenticado sin CRUD de precios');
select ok(has_function_privilege('anon','public.read_catalog()','execute'),'Anónimo puede leer proyección');
select ok(has_function_privilege('authenticated','public.read_catalog()','execute'),'Autenticado puede leer proyección');
select ok((select prosecdef and provolatile='s' from pg_proc where oid='public.read_catalog()'::regprocedure),'RPC estable security definer');
select ok((select proconfig @> array['search_path=""'] from pg_proc where oid='public.read_catalog()'::regprocedure),'search_path vacío');
select is((select jsonb_array_length(public.read_catalog()->'items')),17,'H8 publica únicamente contenido y modalidades confirmados');
select ok(not (public.read_catalog()->'items'->0 ? 'sourcePriceCents'),'Precio fuente privado');
select ok(not (public.read_catalog()->'items'->0 ? 'deletedBy'),'Autor de borrado privado');
select throws_ok('delete from public.catalog_items where source_ref=''C01''','P0001','FORBIDDEN','No hay borrado físico');
select throws_ok('update public.categories set deleted_at=now() where slug=''promociones''','23514',null,'Borrado exige autor y motivo');
select throws_ok('update public.categories set deleted_at=now(),deleted_by=''99999999-9999-4999-8999-999999999999'',delete_reason=''  Motivo válido de prueba  '' where slug=''promociones''','23514',null,'Motivo debe estar recortado, además de cumplir longitud');
select * from finish();
rollback;
